// Helper function to dynamically allocate MapInfo structs
MapInfo* dynamicMap(short* templateData, u8 rows, u8 cols) {
    MapInfo* info = (MapInfo*)malloc(sizeof(MapInfo));
    info->data = templateData;
    info->rows = rows;
    info->cols = cols;
    return info;
}

